import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 505;
    static int n, m, mod;
    static int[] factorial = new int[MAXN * 4];
    static int[] inv_factorial = new int[MAXN * 4];

    static int update(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void add(int[] x, int y) {
        x[0] = update(x[0] + y);
    }

    static int power(int x, int k) {
        int ans = 1;
        while (k > 0) {
            if ((k & 1) == 1) ans = (int) ((long) ans * x % mod);
            x = (int) ((long) x * x % mod);
            k >>= 1;
        }
        return ans;
    }

    static void initialize(int n) {
        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = (int) ((long) factorial[i - 1] * i % mod);
        }
        inv_factorial[n] = power(factorial[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv_factorial[i] = (int) ((long) inv_factorial[i + 1] * (i + 1) % mod);
        }
    }

    static int C(int n, int m) {
        if (n < 0 || m < 0 || n < m) return 0;
        return (int) ((long) factorial[n] * inv_factorial[n - m] % mod * inv_factorial[m] % mod);
    }

    static List<Integer> multiply(List<Integer> A, List<Integer> B) {
        int sizeA = A.size();
        int sizeB = B.size();
        List<Integer> C = new ArrayList<>(Collections.nCopies(sizeA + sizeB - 1, 0));
        for (int i = 0; i < sizeA; i++) {
            for (int j = 0; j < sizeB; j++) {
                int val = (int) ((long) A.get(i) * B.get(j) % mod);
                C.set(i + j, update(C.get(i + j) + val));
            }
        }
        return C;
    }

    static int sumN(int n) {
        return n * (n + 1) / 2;
    }

    static int G(int n, int m) {
        return C(m + n - 1, n - 1);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        m = Integer.parseInt(st.nextToken());
        n = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        initialize(m << 1);

        List<Integer> f = new ArrayList<>(Collections.nCopies(n + 1, 0));
        List<Integer> g = new ArrayList<>(Collections.nCopies(n + 1, 0));
        f.set(0, 1);

        for (int i = 1; i <= n; i++) {
            int sum = 0;
            for (int j = 0; j < i; j++) {
                int val = (int) ((long) f.get(j) * f.get(i - 1 - j) % mod);
                val = (int) ((long) val * C(i - 1, j) % mod);
                sum = (sum + val) % mod;
            }
            int temp = (int) ((long) sum * (i + 1) % mod);
            f.set(i, temp);
        }

        for (int i = 1; i <= n; i++) {
            int sum = 0;
            for (int j = 0; j < i; j++) {
                int term1 = (int) ((long) f.get(j) * g.get(i - 1 - j) % mod);
                term1 = (int) ((long) term1 * C(i - 1, j) % mod);
                term1 = (int) ((long) term1 * (i + 1) % mod);

                int term2 = (int) ((long) C(i - 1, j) * (sumN(j) + sumN(i - 1 - j)) % mod);
                term2 = (int) ((long) term2 * f.get(j) % mod);
                term2 = (int) ((long) term2 * f.get(i - 1 - j) % mod);

                sum = (sum + term1 + term2) % mod;
            }
            g.set(i, sum);
        }

        f.set(0, 0);
        for (int i = 0; i <= n; i++) {
            g.set(i, (int) ((long) g.get(i) * inv_factorial[i] % mod));
            f.set(i, (int) ((long) f.get(i) * inv_factorial[i] % mod));
        }

        int ans = 0;
        for (int i = 1; i <= m - n + 1; i++) {
            int term = (int) ((long) g.get(n) * G(i + 1, m - n - i + 1) % mod);
            term = (int) ((long) term * factorial[n] % mod);
            term = (int) ((long) term * i % mod);
            ans = (ans + term) % mod;

            g = multiply(g, f);
            g = g.subList(0, n + 1);
        }

        System.out.println(ans);
    }
}
